<?php
use CmuLms\View;
?>
<?php if (!empty($announcements)): ?><details class="card"><summary><strong>Announcement attachments</strong></summary><?php foreach ($announcements as $announcement): $attachments = \CmuLms\Announcement::attachments((int) $announcement['id']); if ($attachments): ?><article><h3><?=View::e($announcement['title'])?></h3><?php foreach ($attachments as $attachment): ?><p><a class="btn" href="?route=announcement-attachment-file&amp;id=<?=View::e($attachment['id'])?>"><?=View::e($attachment['original_name'])?></a></p><?php endforeach; ?></article><?php endif; if (($user['role'] ?? '') === 'teacher' || ($user['role'] ?? '') === 'admin'): ?><form method="post" action="?route=announcement-attachment" enctype="multipart/form-data" class="grid"><?=View::csrfField()?><input type="hidden" name="announcement_id" value="<?=View::e($announcement['id'])?>"><input type="file" name="file" accept=".pdf,.pptx,.doc,.docx,.png,.jpg,.jpeg,.txt" required><button>Attach to “<?=View::e($announcement['title'])?>”</button></form><?php endif; endforeach; ?></details><?php endif; ?>
